def reward(quality, acc, a_tgt):
    # 质量为主，未达加速目标时给惩罚
    return quality - 10.0 * max(0.0, a_tgt - acc)

import torch.nn as nn
class TermErrProxy(nn.Module):
    def __init__(self, dz, de=1, h=128):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(dz + de, h), nn.ReLU(), nn.Linear(h, 1))
    def forward(self, z_t, e_step):
        return self.net(torch.cat([z_t, e_step], dim=-1))
